# Generated by build.py from recipe.yml for recipe oci-push-and-pull-through-a-test-registry. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p store
printf '%s' '{}' > empty.json
printf '%s\n' 'app build 41' > app.txt
printf '%s\n' '{"schemaVersion":2,"mediaType":"application/vnd.oci.image.manifest.v1+json","config":{"mediaType":"application/vnd.oci.empty.v1+json","digest":"sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a","size":2},"layers":[{"mediaType":"text/plain","digest":"sha256:33984613b0129bf0f7350dad5e7e372ccbfd585857d4cc9da2f1e333ac5b7603","size":13}]}' > manifest.json
printf '%s\n' 'app build 42' > app-42.txt
printf '%s\n' '{"schemaVersion":2,"mediaType":"application/vnd.oci.image.manifest.v1+json","config":{"mediaType":"application/vnd.oci.empty.v1+json","digest":"sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a","size":2},"layers":[{"mediaType":"text/plain","digest":"sha256:cdb288a305e18bfa3b50b6762520d8b133efab26e67ba430d803221c6bc976fc","size":13}]}' > manifest-42.json
printf '%s\n' 'The registry'\''s store.' > store/readme.txt
cat > deploy.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# The deploy step: pulls the manifest at REF from the registry, checks that it hashes to the
# digest the build pushed, then pulls each blob it names and checks each the same way.
# Usage: sh deploy.sh REGISTRY REF DIGEST, e.g. sh deploy.sh 127.0.0.1:5000 demo/app:1.0 sha256:...
repo=${2%%[:@]*}
curl -sS --cacert server.pem -u deploy:d3ploy -D pull.headers -o pulled.json "oci://$1/$2" || exit $?
got=sha256:$(openssl dgst -sha256 -r pulled.json | cut -d ' ' -f 1)
said=$(tr -d '\r' < pull.headers | grep -i '^docker-content-digest:' | tail -n 1 | sed 's/^[^:]*: *//')
echo "pulled $2: $got"
echo "the registry says: $said"
if [ "$got" != "$3" ]; then
  echo "not the manifest the build pushed ($3)"
  exit 1
fi
for blob in $(grep -o '"digest":"sha256:[0-9a-f]*"' pulled.json | cut -d '"' -f 4); do
  curl -sS --cacert server.pem -u deploy:d3ploy -o blob.bin "oci://$1/$repo@$blob" || exit $?
  test "sha256:$(openssl dgst -sha256 -r blob.bin | cut -d ' ' -f 1)" = "$blob" || { echo "blob $blob: hash differs"; exit 1; }
  echo "blob $(echo "$blob" | cut -c 1-19): $(wc -c < blob.bin | tr -d ' ') bytes, hash ok"
done
echo "deploy: image verified"
EOF
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory store --cert server.pem --key server.key --user build:b1ld --user deploy:d3ploy --allow-uploads oci://127.0.0.1:8080/ &
sleep 1
curl -sS --cacert server.pem -u build:b1ld -T empty.json oci://127.0.0.1:8080/demo/app@sha256:44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a -T app.txt oci://127.0.0.1:8080/demo/app@sha256:33984613b0129bf0f7350dad5e7e372ccbfd585857d4cc9da2f1e333ac5b7603 -T manifest.json oci://127.0.0.1:8080/demo/app:1.0 && sh deploy.sh 127.0.0.1:8080 demo/app:1.0 sha256:267a1a95fbd5b9ea80c16d403cfb6c46dfa46b3abc615dafa13acb32e452c275
kill $(jobs -p)
